-- Disposable test cluster only; all synthetic users are rolled back.
begin;
create function pg_temp.assert_true(condition boolean,label text) returns void language plpgsql as $$
begin if condition is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(statement text,code text,label text) returns void language plpgsql as $$
declare failed boolean:=false;begin begin execute statement;exception when others then if sqlstate<>code then raise exception 'FAIL: % expected % got %',label,code,sqlstate;end if;failed:=true;end;if not failed then raise exception 'FAIL: % unexpectedly succeeded',label;end if;raise notice 'PASS: %',label;end;$$;
insert into auth.users(id) values('00000000-0000-4000-a000-000000000001'),('00000000-0000-4000-a000-000000000002'),('00000000-0000-4000-a000-000000000003');
update public.profiles set username=case id when '00000000-0000-4000-a000-000000000001' then 'alice' when '00000000-0000-4000-a000-000000000002' then 'bob' else 'charlie' end,display_name='Test maker';
insert into public.projects(id,maker_id,name,tagline,description,category_id,status,published_at,publish_request_key,release_url) values
('10000000-0000-4000-a000-000000000001','00000000-0000-4000-a000-000000000001','Following fixture','A shipped following test fixture',repeat('Description. ',20),(select id from public.categories where slug='developer-tools'),'published',now(),gen_random_uuid(),'https://example.test/following');

set local role anon;
select pg_temp.expect_error($q$select public.create_collection(gen_random_uuid(),'Private actor','')$q$,'42501','anonymous collection writes denied');
select pg_temp.expect_error($q$select public.get_my_notification_status()$q$,'42501','anonymous notification reads denied');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true(public.create_collection('70000000-0000-4000-a000-000000000001','Tools','Useful work')='70000000-0000-4000-a000-000000000001'::uuid,'create collection returns stable id');
select public.create_collection('70000000-0000-4000-a000-000000000001','Tools','Useful work');
select pg_temp.assert_true((select count(*)=1 from public.list_collections('00000000-0000-4000-a000-000000000002')),'creation retries deduplicate');
select pg_temp.assert_true(public.set_collection_item('10000000-0000-4000-a000-000000000001',null,true)->>'saved'='true','first save creates Saved and membership');
select public.set_collection_item('10000000-0000-4000-a000-000000000001',null,true);
select public.set_collection_item('10000000-0000-4000-a000-000000000001','70000000-0000-4000-a000-000000000001',true);
select pg_temp.assert_true((select count(*)=2 from public.collection_items),'multiple memberships are unique');
select pg_temp.assert_true((select count(*)=1 from public.get_my_saved_projects(array['10000000-0000-4000-a000-000000000001'::uuid])),'saved indicator deduplicates multiple memberships');
select pg_temp.assert_true(public.set_collection_item('10000000-0000-4000-a000-000000000001',null,false)->>'saved'='true','removing one membership keeps saved state');
select pg_temp.expect_error($q$update public.collections set owner_id='00000000-0000-4000-a000-000000000001'$q$,'42501','direct collection ownership tampering denied');
select pg_temp.expect_error($q$select public.update_collection((select id from public.collections where is_default),'Other','')$q$,'42501','Saved cannot be renamed');
reset role;
set local role anon;
select pg_temp.assert_true((select count(*)=2 from public.list_collections('00000000-0000-4000-a000-000000000002')),'collections including Saved are public');
select pg_temp.assert_true((select count(*)=1 from public.list_collection_projects('70000000-0000-4000-a000-000000000001')),'public collection reader shows visible work');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000003',true);
set local role authenticated;
select pg_temp.expect_error($q$select public.update_collection('70000000-0000-4000-a000-000000000001','Stolen','')$q$,'42501','other user cannot edit collection');
select pg_temp.expect_error($q$select public.delete_collection('70000000-0000-4000-a000-000000000001')$q$,'42501','other user cannot delete collection');
select pg_temp.expect_error($q$select public.set_collection_item('10000000-0000-4000-a000-000000000001','70000000-0000-4000-a000-000000000001',true)$q$,'42501','other user cannot change memberships');
reset role;
update public.projects set status='hidden' where id='10000000-0000-4000-a000-000000000001';
set local role anon;
select pg_temp.assert_true((select count(*)=0 from public.list_collection_projects('70000000-0000-4000-a000-000000000001')),'hidden work disappears from public collections');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select pg_temp.expect_error($q$select public.set_collection_item('10000000-0000-4000-a000-000000000001',null,true)$q$,'22023','hidden work cannot be added');
select pg_temp.assert_true(public.set_collection_item('10000000-0000-4000-a000-000000000001','70000000-0000-4000-a000-000000000001',false)->>'saved'='false','unavailable saved work can be removed');
select public.delete_collection('70000000-0000-4000-a000-000000000001');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.projects),'deleting collection does not delete its projects');
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000002';
set local role anon;
select pg_temp.assert_true((select count(*)=0 from public.list_collections('00000000-0000-4000-a000-000000000002')),'suspended owners collections disappear');
reset role;
update private.account_controls set status='active' where user_id='00000000-0000-4000-a000-000000000002';
insert into public.notifications(id,recipient_id,actor_id,type,dedupe_key) values
('80000000-0000-4000-a000-000000000001','00000000-0000-4000-a000-000000000002','00000000-0000-4000-a000-000000000001','follow','test:old'),
('80000000-0000-4000-a000-000000000002','00000000-0000-4000-a000-000000000003','00000000-0000-4000-a000-000000000001','follow','test:other');
set local role authenticated;
select pg_temp.assert_true(public.get_my_notification_status()->>'unread'='1','unread totals only include recipient');
select pg_temp.assert_true((select count(*)=1 from public.list_my_notifications()),'recipient notification list is isolated');
select public.mark_my_notifications_read(array['80000000-0000-4000-a000-000000000002'::uuid],null);
select pg_temp.assert_true(public.get_my_notification_status()->>'unread'='1','marking another recipient id has no effect');
select public.mark_my_notifications_read(array['80000000-0000-4000-a000-000000000001'::uuid],null);
select pg_temp.assert_true(public.get_my_notification_status()->>'unread'='0','mark read changes recipient unread count');
select public.update_my_notification_preferences(false,true,false);
select pg_temp.assert_true(public.get_my_notification_preferences()='{"follows":false,"upvotes":true,"launches":false}'::jsonb,'private preferences persist');
select pg_temp.expect_error($q$select public.mark_my_notifications_read(null,now()+interval '1 day')$q$,'22023','future mark-all cutoff rejected');
reset role;
select pg_temp.assert_true((select read_at is null from public.notifications where id='80000000-0000-4000-a000-000000000002'),'other recipient event stays unread');
insert into public.notifications(recipient_id,actor_id,type,dedupe_key,created_at) values('00000000-0000-4000-a000-000000000002','00000000-0000-4000-a000-000000000001','follow','test:new',now()+interval '1 minute');
set local role authenticated;
select public.mark_my_notifications_read(null,now());
select pg_temp.assert_true(public.get_my_notification_status()->>'unread'='1','events arriving after mark-all cutoff stay unread');
reset role;
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000001';
set local role authenticated;
select pg_temp.assert_true((select bool_and(actor_username is null and actor_name is null) from public.list_my_notifications()),'unavailable actor details are removed from notification DTO');
reset role;
update public.notifications set withdrawn_at=now() where recipient_id='00000000-0000-4000-a000-000000000002';
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.list_my_notifications()),'withdrawn events disappear');
reset role;
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000002';
set local role authenticated;
select pg_temp.expect_error($q$select public.get_my_notification_status()$q$,'42501','suspended recipients cannot read notifications');
select pg_temp.expect_error($q$select public.create_collection(gen_random_uuid(),'Blocked','')$q$,'42501','suspended user cannot create collections');
reset role;
rollback;
